// YAML ↔ JSON Converter
// Basic YAML parser - supports objects, arrays, strings, numbers, booleans

var mode = input.get("mode") || "toJson";
var inputText = input.get("inputText");
var indent = parseInt(input.get("indent") || "2");

if (!inputText || inputText.trim() === "") {
    log.error("Input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Input is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        var result = "";

        if (mode.toLowerCase() === "toyaml" || mode.toLowerCase() === "encode") {
            // JSON to YAML
            var data = json.parse(inputText);

            function toYaml(obj, level) {
                var spaces = "";
                for (var s = 0; s < level * indent; s++) spaces += " ";
                var lines = [];

                if (Array.isArray(obj)) {
                    for (var i = 0; i < obj.length; i++) {
                        var item = obj[i];
                        if (typeof item === "object" && item !== null) {
                            lines.push(spaces + "-");
                            var subLines = toYaml(item, level + 1).split('\n');
                            for (var j = 0; j < subLines.length; j++) {
                                if (subLines[j].trim()) lines.push(subLines[j]);
                            }
                        } else {
                            lines.push(spaces + "- " + formatValue(item));
                        }
                    }
                } else if (typeof obj === "object" && obj !== null) {
                    var keys = Object.keys(obj);
                    for (var k = 0; k < keys.length; k++) {
                        var key = keys[k];
                        var val = obj[key];
                        if (typeof val === "object" && val !== null) {
                            lines.push(spaces + key + ":");
                            var subLines = toYaml(val, level + 1).split('\n');
                            for (var m = 0; m < subLines.length; m++) {
                                if (subLines[m].trim()) lines.push(subLines[m]);
                            }
                        } else {
                            lines.push(spaces + key + ": " + formatValue(val));
                        }
                    }
                }
                return lines.join('\n');
            }

            function formatValue(v) {
                if (v === null) return "null";
                if (v === true) return "true";
                if (v === false) return "false";
                if (typeof v === "number") return String(v);
                if (typeof v === "string") {
                    if (v.indexOf(':') >= 0 || v.indexOf('#') >= 0 || v.indexOf('\n') >= 0 || v.match(/^[\[\]{}&*!|>'"%@`]/) || v === "") {
                        return '"' + v.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n') + '"';
                    }
                    return v;
                }
                return String(v);
            }

            result = toYaml(data, 0);
            log.info("Converted JSON to YAML");
        } else {
            // YAML to JSON (basic parser)
            var lines = inputText.split('\n');
            var root = {};
            var stack = [{obj: root, indent: -1}];
            var currentArray = null;

            function parseValue(str) {
                str = str.trim();
                if (str === "null" || str === "~") return null;
                if (str === "true") return true;
                if (str === "false") return false;
                if (str.match(/^-?\d+$/)) return parseInt(str);
                if (str.match(/^-?\d*\.\d+$/)) return parseFloat(str);
                if ((str.charAt(0) === '"' && str.charAt(str.length-1) === '"') || 
                    (str.charAt(0) === "'" && str.charAt(str.length-1) === "'")) {
                    return str.substring(1, str.length - 1);
                }
                return str;
            }

            function getIndent(line) {
                var count = 0;
                for (var i = 0; i < line.length; i++) {
                    if (line[i] === ' ') count++;
                    else break;
                }
                return count;
            }

            for (var i = 0; i < lines.length; i++) {
                var line = lines[i];
                var trimmed = line.trim();
                if (trimmed === "" || trimmed.charAt(0) === '#') continue;

                var lineIndent = getIndent(line);

                // Pop stack to correct level
                while (stack.length > 1 && stack[stack.length-1].indent >= lineIndent) {
                    stack.pop();
                }
                var parent = stack[stack.length-1].obj;

                if (trimmed.charAt(0) === '-') {
                    // Array item
                    var val = trimmed.substring(1).trim();
                    if (!Array.isArray(parent)) {
                        // Need to convert parent's last key to array
                        var lastKey = stack[stack.length-1].key;
                        if (lastKey) {
                            var parentObj = stack.length > 1 ? stack[stack.length-2].obj : root;
                            parentObj[lastKey] = [];
                            parent = parentObj[lastKey];
                            stack[stack.length-1].obj = parent;
                        }
                    }
                    if (val.indexOf(':') > 0) {
                        var colonIdx = val.indexOf(':');
                        var k = val.substring(0, colonIdx).trim();
                        var v = val.substring(colonIdx + 1).trim();
                        var newObj = {};
                        newObj[k] = parseValue(v);
                        parent.push(newObj);
                        stack.push({obj: newObj, indent: lineIndent, key: k});
                    } else if (val) {
                        parent.push(parseValue(val));
                    } else {
                        var newObj = {};
                        parent.push(newObj);
                        stack.push({obj: newObj, indent: lineIndent});
                    }
                } else if (trimmed.indexOf(':') > 0) {
                    var colonIdx = trimmed.indexOf(':');
                    var key = trimmed.substring(0, colonIdx).trim();
                    var val = trimmed.substring(colonIdx + 1).trim();

                    if (val === '' || val.charAt(0) === '#') {
                        // Object or array follows
                        parent[key] = {};
                        stack.push({obj: parent[key], indent: lineIndent, key: key});
                    } else {
                        parent[key] = parseValue(val);
                    }
                }
            }

            result = json.stringify(root);
            log.info("Converted YAML to JSON");
        }

        output.set("Result", result);
        output.set("Mode", mode);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        tags.trigger("success");

    } catch (ex) {
        log.error("Conversion failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}
